a:2:{s:9:"customCss";s:4246:".blink-link {
  animation: blinkLink 1s infinite;
}

@keyframes blinkLink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0; }
}
/* OUTER CLICKABLE CARD */
.prelims-cta {
  display: block;
  text-decoration: none;
  border-radius: 24px;
  background: linear-gradient(135deg, #ff9800, #e65100);
  padding: 18px 26px;
  box-shadow: 0 10px 25px rgba(0,0,0,0.16);
  color: #fff;
  transition: transform 0.25s ease, box-shadow 0.25s ease;
  position: relative;
  overflow: hidden;
}

/* Inner flex layout */
.prelims-cta-inner {
  display: flex;
  align-items: center;
  gap: 18px;
}

/* Icon / image */
.prelims-cta-icon {
  font-size: 40px;
  flex-shrink: 0;
}

/* Text area */
.prelims-cta-text {
  display: flex;
  flex-direction: column;
}

/* Main title */
.prelims-cta-title {
  font-size: 20px;
  font-weight: 700;
  margin-bottom: 4px;
}

/* Sub text */
.prelims-cta-sub {
  font-size: 14px;
  opacity: 0.9;
}

/* Remove default link color/underline */
.prelims-cta,
.prelims-cta:visited {
  color: #fff;
}

/* Hover effect: lift + stronger shadow */
.prelims-cta:hover {
  transform: translateY(-4px);
  box-shadow: 0 16px 35px rgba(0,0,0,0.22);
}

/* Subtle shine animation on hover */
.prelims-cta::before {
  content: "";
  position: absolute;
  top: 0;
  left: -80px;
  width: 60px;
  height: 100%;
  background: linear-gradient(120deg, rgba(255,255,255,0.0), rgba(255,255,255,0.5), rgba(255,255,255,0.0));
  transform: skewX(-20deg);
  opacity: 0;
  pointer-events: none;
}

.prelims-cta:hover::before {
  opacity: 1;
  animation: csap-shine 0.7s forwards;
}

/* Shine keyframes */
@keyframes csap-shine {
  0% { transform: translateX(0) skewX(-20deg); }
  100% { transform: translateX(260%) skewX(-20deg); }
}

/* Responsive */
@media (max-width: 600px) {
  .prelims-cta-inner {
    flex-direction: row;
    align-items: flex-start;
  }
  .prelims-cta-title {
    font-size: 18px;
  }
}
/* Base style */
.premium-text-link {
  font-size: 22px;
  font-weight: 700;
  color: #E65100;
  text-decoration: none;
  position: relative;
  display: inline-block;
  cursor: pointer;
  transition: color 0.25s ease;
}

/* Underline animation */
.premium-text-link::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: -4px;
  width: 0%;
  height: 3px;
  background: #E65100;
  border-radius: 3px;
  transition: width 0.35s ease;
}

/* Hover effects */
.premium-text-link:hover {
  color: #BF4500;
}

.premium-text-link:hover::after {
  width: 100%;
}

/* Fade-up scroll animation (works with your existing JS) */
.csap-animate {
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 0.7s ease, transform 0.7s ease;
}

.csap-animate.animate-in {
  opacity: 1;
  transform: translateY(0);
}
/* Premium Gradient Text Link */
.premium-text-cta {
  font-size: 28px;
  font-weight: 700;
  background: linear-gradient(90deg, #ff8a00, #e65100);
  -webkit-background-clip: text;
  color: transparent;
  text-decoration: none;
  position: relative;
  display: inline-block;
  cursor: pointer;
  transition: opacity 0.25s ease;
}

/* Hover gradient glow */
.premium-text-cta:hover {
  opacity: 0.85;
}

/* Underline reveal */
.premium-text-cta::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: -6px;
  width: 0%;
  height: 3px;
  background: linear-gradient(90deg, #ff8a00, #e65100);
  border-radius: 3px;
  transition: width 0.35s ease;
}

.premium-text-cta:hover::after {
  width: 100%;
}

/* Arrow animation */
.cta-arrow {
  display: inline-block;
  margin-left: 8px;
  transition: transform 0.3s ease;
  font-size: 28px;
}

.premium-text-cta:hover .cta-arrow {
  transform: translateX(6px);
}

/* Fade-up scroll animation */
.csap-animate {
  opacity: 0;
  transform: translateY(22px);
  transition: opacity 0.8s ease, transform 0.8s ease;
}

.csap-animate.animate-in {
  opacity: 1;
  transform: translateY(0);
}


html, body {
  margin: 0 !important;
  padding: 0 !important;
  height: auto !important;
  overflow-x: hidden;
}

/* Remove extra space after footer */
body::after {
  display: none !important;
  content: none !important;
}

/* Footer fix */
footer {
  margin-bottom: 0 !important;
  padding-bottom: 0 !important;
}
#brx-content {
  margin-bottom: 0 !important;
  padding-bottom: 0 !important;
}";s:23:"customScriptsBodyFooter";s:279:"<script>
const reveals = document.querySelectorAll('.reveal');
window.addEventListener('scroll', () => {
  reveals.forEach(el => {
    const top = el.getBoundingClientRect().top;
    if (top < window.innerHeight - 80) {
      el.classList.add('active');
    }
  });
});
</script>";}

