/* Ensure header & footer always visible */
header,
.site-header,
.brxe-header,
footer,
.site-footer,
.brxe-footer {
  position: relative !important;
  z-index: 99999 !important;
}

/* ================= KRDC WRAPPER ================= */
#krdc-coaching {
  position: relative;
  z-index: 1;
  max-width: 1200px;
  margin: 0 auto;
  padding: 40px 20px;
}

/* ================= BACKGROUND EFFECTS ================= */
#krdc-coaching .parallax-bg,
#krdc-coaching .floating-shapes {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}

/* Parallax layers */
.parallax-layer.l1 {
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, rgba(179,0,0,0.12), transparent 60%);
  position: absolute;
  top: -120px;
  left: -120px;
  filter: blur(20px);
}

.parallax-layer.l2 {
  width: 420px;
  height: 420px;
  background: radial-gradient(circle, rgba(179,0,0,0.08), transparent 60%);
  position: absolute;
  bottom: -120px;
  right: -120px;
  filter: blur(24px);
}

/* Floating shapes */
.shape {
  position: absolute;
  border-radius: 50%;
  filter: blur(30px);
  opacity: 0.6;
}
.shape.s1 {
  width: 260px;
  height: 260px;
  background: #ffb3b3;
  top: 10%;
  left: -120px;
}
.shape.s2 {
  width: 200px;
  height: 200px;
  background: #ffd6d6;
  bottom: 10%;
  right: -100px;
}

/* ================= CONTENT ABOVE BACKGROUND ================= */
#krdc-coaching > * {
  position: relative;
  z-index: 2;
}

/* ================= HERO ================= */
.hero {
  background: linear-gradient(135deg, #8a0000, #b30000);
  color: #fff;
  border-radius: 20px;
  padding: 60px 30px;
  margin-bottom: 40px;
  overflow: hidden;
}
.hero h1 {
  margin: 0;
  font-size: clamp(26px, 4vw, 40px);
}
.hero p {
  margin-top: 14px;
  max-width: 900px;
  line-height: 1.6;
}

/* Wave */
.wave {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
}

/* ================= CARDS ================= */
.card {
  background: #fff;
  border-radius: 16px;
  padding: 30px;
  margin-bottom: 30px;
  box-shadow: 0 12px 30px rgba(0,0,0,0.08);
}
.card h2 {
  margin-top: 0;
}

/* ================= BUTTONS ================= */
.btn {
  display: inline-block;
  margin-top: 16px;
  padding: 12px 24px;
  background: linear-gradient(90deg, #9b0000, #d60000);
  color: #fff;
  border-radius: 10px;
  font-weight: 700;
  text-decoration: none;
  transition: all 0.3s ease;
}
.btn:hover {
  transform: translateY(-3px);
  box-shadow: 0 12px 28px rgba(214,0,0,0.4);
}

/* ================= NOTICE BUTTON ================= */
.notice-btn {
  display: inline-block;
  margin: 10px 10px 0 0;
  padding: 10px 18px;
  background: #8a0000;
  color: #fff;
  border-radius: 8px;
  font-weight: 600;
  text-decoration: none;
}

/* ================= SCROLL REVEAL ================= */
.reveal {
  opacity: 0;
  transform: translateY(40px);
  transition: all 0.8s ease;
}
.reveal.in-view {
  opacity: 1;
  transform: none;
}

/* ================= MOBILE ================= */
@media (max-width: 768px) {
  #krdc-coaching {
    padding: 20px 14px;
  }
  .hero {
    padding: 40px 20px;
  }
}
</style>

