a:1:{s:9:"customCss";s:11632:"/* ---------- Replace big shapes with safe centered decoration ---------- */

/* hide old shape children if still present */
.page-shape .shape-1,
.page-shape .shape-2 { display: none !important; }

/* make .page-shape a simple, clipped decorative layer using gradients */
.page-shape {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  overflow: hidden; /* ensures nothing bleeds out */
  background: radial-gradient(40% 40% at 10% 12%, rgba(138,0,0,0.06), transparent 35%),
              radial-gradient(35% 35% at 92% 78%, rgba(178,47,47,0.04), transparent 40%),
              linear-gradient(180deg, rgba(255,255,255,0.00) 0%, rgba(250,248,246,0.35) 100%);
  mix-blend-mode: normal;
  transform: translateZ(0);
}

/* small soft diagonal wash near the top-right for subtle texture */
.page-shape::before{
  content: "";
  position: absolute;
  right: -6vw;
  top: -6vh;
  width: 40vw;
  height: 40vh;
  background: linear-gradient(135deg, rgba(138,0,0,0.03), rgba(255,255,255,0));
  filter: blur(20px);
  pointer-events: none;
}

/* ensure no horizontal overflow caused by decorations */
html, body { overflow-x: hidden !important; }

/* reduce visual intensity on small screens (keeps it lightweight) */
@media (max-width: 880px) {
  .page-shape { background: radial-gradient(50% 40% at 10% 12%, rgba(138,0,0,0.04), transparent 40%); }
  .page-shape::before { display: none; }
}
/* EMERGENCY: Prevent any horizontal overflow and clip decorations */
html, body {
  overflow-x: hidden !important;
  max-width: 100% !important;
}

/* Ensure every element can't push page wider */
* {
  box-sizing: border-box !important;
  max-width: 100vw !important;
  word-wrap: break-word !important;
}

/* Hide or clip decorative / risky layers */
.page-shape, .shape-1, .shape-2, .hero-overlay, .floating-deco {
  display: none !important;
  max-width: 100% !important;
  overflow: hidden !important;
}

/* Make hero compact and centered */
.hero {
  width: 100% !important;
  max-width: 100% !important;
  margin-left: auto !important;
  margin-right: auto !important;
  padding-left: 16px !important;
  padding-right: 16px !important;
  overflow: hidden !important;
}

/* Images & svg should never overflow */
img, svg, video, iframe {
  max-width: 100% !important;
  height: auto !important;
  display: block;
}

/* Force container centering */
.container {
  width: 100% !important;
  max-width: 980px !important;
  margin-left: auto !important;
  margin-right: auto !important;
  padding-left: 12px !important;
  padding-right: 12px !important;
  overflow: visible !important;
}

/* Fix fixed-positioned elements that may stick out (eg. chat widgets) */
*[style*="position:fixed"], .whatsapp, .whatsapp-widget, .wh-widget, .floating-chat {
  right: 12px !important;
  left: auto !important;
  max-width: calc(100vw - 24px) !important;
}

/* Reduce large shadows/margins that create appearance of space */
body > * { margin-right: 0 !important; padding-right: 0 !important; }

/* Mobile safety */
@media (max-width: 880px) {
  html, body { overflow-x: hidden !important; }
  .container { padding-left: 10px !important; padding-right: 10px !important; }
}
/* ---------- Force full-centered layout, remove left/right gaps ---------- */
/* Apply at top of your custom CSS so it overrides theme/plugin rules */

html, body {
  margin: 0 !important;
  padding: 0 !important;
  width: 100% !important;
  overflow-x: hidden !important; /* prevent horizontal overflow */
  box-sizing: border-box !important;
}

/* Common theme wrapper names — make them full-width and centered */
.site, .site-wrapper, .page-wrap, .page, .main-wrapper, .site-content, .content-area, .wrap, .container {
  max-width: 980px !important;
  width: calc(100% - 40px) !important; /* keeps symmetric gutters */
  margin-left: auto !important;
  margin-right: auto !important;
  padding-left: 20px !important;
  padding-right: 20px !important;
  box-sizing: border-box !important;
}

/* Force hero and cards to use same centered container (no large left indent) */
.hero, header.hero, .page-hero, .hero-content, .card {
  margin-left: auto !important;
  margin-right: auto !important;
  padding-left: 20px !important;
  padding-right: 20px !important;
  max-width: 100% !important;
  box-sizing: border-box !important;
}

/* Ensure nav/header logo won't push content */
.site-header, header.site-header, .topbar, .header-inner, .navbar {
  padding-left: 12px !important;
  padding-right: 12px !important;
  margin: 0 !important;
  width: 100% !important;
  box-sizing: border-box !important;
}

/* Prevent any element from forcing a wider page */
* {
  max-width: 100vw !important;
  box-sizing: border-box !important;
}

/* Clamp large fixed/floating widgets (chat icons etc.) */
*[style*="position:fixed"], .whatsapp, .wh-widget, .floating-chat, .floating-button {
  right: 12px !important;
  left: auto !important;
  max-width: calc(100vw - 24px) !important;
}

/* Hide old decorative shapes that may push layout */
.page-shape, .shape-1, .shape-2, .floating-deco, .hero-overlay {
  display: none !important;
}

/* Mobile tweaks */
@media (max-width: 880px) {
  .site, .container { width: calc(100% - 20px) !important; padding-left:10px !important; padding-right:10px !important; }
  .hero, .card { padding-left: 12px !important; padding-right: 12px !important; border-radius:10px; }
  html, body { overflow-x: hidden !important; }
}
/* ------------------------------------------------ */
/* BEAUTIFUL HERO WAVE ANIMATION + FLOAT EFFECTS    */
/* ------------------------------------------------ */

/* smooth fade-in for hero */
.hero {
  animation: heroFade 1.2s ease-out forwards;
  opacity: 0;
}

@keyframes heroFade {
  from { opacity: 0; transform: translateY(30px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* animated wave motion */
.wave-move path {
  animation: waveMove 8s ease-in-out infinite alternate;
}

@keyframes waveMove {
  0%   { d: path("M0,0 C200,60 400,0 600,40 C800,80 1000,20 1200,40 L1200,120 L0,120 Z"); }
  100% { d: path("M0,0 C200,90 400,10 600,60 C800,110 1000,40 1200,60 L1200,120 L0,120 Z"); }
}

/* ------------------------------------------------ */
/* CARD ANIMATION — smooth fade + slight pop        */
/* ------------------------------------------------ */

.card {
  animation: cardPop 0.9s ease-out forwards;
  opacity: 0;
  transform: translateY(20px);
}

@keyframes cardPop {
  0%   { opacity: 0; transform: translateY(30px) scale(0.97); }
  100% { opacity: 1; transform: translateY(0) scale(1); }
}

/* hover effect */
.card:hover {
  transform: translateY(-4px) scale(1.01);
  box-shadow: 0 12px 30px rgba(0,0,0,0.08);
  transition: 0.3s ease;
}
/* ---------- KRDC Coaching : WordPress Custom CSS (paste into Additional CSS) ---------- */

/* scoped container */
#krdc-coaching { max-width:1040px; margin:18px auto; padding:18px; position:relative; z-index:2; font-family:Inter,system-ui,Arial,sans-serif; }

/* parallax background (fixed but clipped) */
#krdc-coaching .parallax-bg{
  position:fixed; inset:0; z-index:0; pointer-events:none; overflow:hidden;
  background:
    radial-gradient(40vw 40vh at 10% 12%, rgba(138,0,0,0.06), transparent 35%),
    radial-gradient(30vw 30vh at 90% 82%, rgba(178,47,47,0.03), transparent 35%),
    linear-gradient(180deg,#fbf8f6 0%, #fffefc 100%);
  clip-path: inset(0 0 0 0);
}

/* parallax layers */
#krdc-coaching .parallax-layer{ position:absolute; will-change:transform; }
#krdc-coaching .parallax-layer.l1 { width:640px; height:640px; left:-8vw; top:-6vh; background:radial-gradient(circle, rgba(138,0,0,0.05), transparent 40%); filter:blur(20px); }
#krdc-coaching .parallax-layer.l2 { width:520px; height:520px; right:-6vw; bottom:-6vh; background:linear-gradient(135deg, rgba(178,47,47,0.03), rgba(10,128,120,0.01)); filter:blur(22px); }

/* floating shapes (clipped & non-intrusive) */
#krdc-coaching .floating-shapes { position:absolute; inset:0; z-index:0; pointer-events:none; overflow:hidden; }
#krdc-coaching .shape { position:absolute; border-radius:50%; opacity:.9; filter:blur(22px); transform:translateZ(0); }
#krdc-coaching .shape.s1{ width:480px;height:480px; left:-6vw; top:-8vh; background: radial-gradient(circle,#8a0000 10%, transparent 45%); }
#krdc-coaching .shape.s2{ width:380px;height:380px; right:-4vw; top:8vh; background: linear-gradient(135deg,#b22f2f 6%, rgba(255,255,255,0) 55%); }

/* hero */
#krdc-coaching .hero{ position:relative; overflow:hidden; border-radius:14px; background:linear-gradient(180deg,#8a0000,#b22f2f); color:#fff; padding:28px 24px; margin-bottom:22px; box-shadow: 0 8px 32px rgba(138,0,0,0.18); text-align:center; border:1px solid rgba(255,255,255,0.03); }
#krdc-coaching .hero .inner{ max-width:900px; margin:0 auto; position:relative; z-index:2; }
#krdc-coaching .hero h1{ margin:0; font-size:1.45rem; letter-spacing:.6px; }
#krdc-coaching .hero p{ margin:.6rem 0 0; opacity:.95; font-size:.98rem; line-height:1.3; }

/* wave */
#krdc-coaching .wave{ position:absolute; left:0; right:0; bottom:0; height:84px; display:block; }
#krdc-coaching .wave svg{ width:100%; height:100%; display:block; }

/* cards */
#krdc-coaching .card{ background:#fff; border-radius:12px; padding:22px; margin-bottom:18px; box-shadow:0 10px 30px rgba(20,20,20,0.06); transform:translateY(8px); opacity:0; transition:transform .35s ease, box-shadow .35s ease, opacity .6s ease; }
#krdc-coaching .card.glow{ border:1px solid rgba(138,0,0,0.06); box-shadow: 0 12px 36px rgba(10,10,10,0.06), 0 0 0 6px rgba(138,0,0,0.02); }

/* buttons */
#krdc-coaching .btn{ display:inline-block; background:linear-gradient(90deg,#0a8,#067); color:#fff; padding:12px 16px; border-radius:10px; text-decoration:none; font-weight:700; transition:transform .18s ease, box-shadow .18s ease; box-shadow: 0 6px 18px rgba(3,100,80,0.08); }
#krdc-coaching .btn:hover{ transform:translateY(-4px) scale(1.02); box-shadow: 0 14px 36px rgba(3,100,80,0.12); }
#krdc-coaching .notice-btn{ display:inline-block; background:#8a0000; color:#fff; padding:10px 14px; border-radius:10px; text-decoration:none; margin-top:10px; font-weight:600; transition: transform .18s ease; }
#krdc-coaching .notice-btn:hover{ transform:translateY(-3px); }

/* reveal animations - will be triggered by JS adding .in-view */
#krdc-coaching .reveal { transform: translateY(22px); opacity:0; transition: all .8s cubic-bezier(.2,.9,.2,1); }
#krdc-coaching .reveal.in-view { transform: translateY(0); opacity:1; }
#krdc-coaching .hero.reveal { transform: translateY(10px); opacity:0; }
#krdc-coaching .hero.reveal.in-view { transform: translateY(0); opacity:1; transition: all .9s cubic-bezier(.2,.9,.2,1); }

/* safety: prevent any overflow from decorations */
html, body { overflow-x:hidden !important; }

/* responsive */
@media (max-width:880px){
  #krdc-coaching{ padding-left:12px; padding-right:12px; }
  #krdc-coaching .hero{ padding:18px; border-radius:10px; }
  #krdc-coaching .hero h1{ font-size:1.05rem; }
  #krdc-coaching .shape.s1, #krdc-coaching .shape.s2, #krdc-coaching .parallax-layer { display:none; }
}
/* ================= FULL WIDTH KRDC PAGE FIX ================= */

/* Remove theme container width for this page */
#krdc-coaching {
  max-width: 100vw !important;
  width: 100vw !important;
  margin-left: calc(50% - 50vw);
  margin-right: calc(50% - 50vw);
