}

/* Remove inner container padding */
#krdc-coaching .hero,
#krdc-coaching .card {
  max-width: 1200px;
  margin-left: auto;
  margin-right: auto;
}

/* Ensure no horizontal scroll */
html, body {
  overflow-x: hidden;
}
