a:2:{s:9:"customCss";s:10497:"/* MAIN WRAPPER */
.csap-mcq-wrapper {
  display: flex;
  flex-wrap: wrap;
  gap: 50px;
  align-items: flex-start;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
}

/* LEFT COLUMN */
.csap-mcq-left {
  flex: 1 1 50%;
  min-width: 280px;
}

.csap-badge-orange {
  display: inline-block;
  padding: 6px 14px;
  background: #FFE8D1;
  color: #E65100;
  border-radius: 50px;
  margin-bottom: 14px;
  font-weight: 600;
}

.csap-mcq-title {
  font-size: 38px;
  font-weight: 700;
  color: #E65100;
  margin-bottom: 10px;
}

.csap-mcq-subtitle {
  font-size: 16px;
  color: #444;
  margin-bottom: 18px;
}

.csap-mcq-list {
  margin: 0 0 14px;
  padding-left: 18px;
}

.csap-mcq-list li {
  margin-bottom: 7px;
}

/* BADGE PILLS */
.csap-exam-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 14px;
}

.csap-pill-red {
  background: #B71C1C;
  color: #fff;
  padding: 6px 16px;
  border-radius: 50px;
  font-weight: 600;
}

.csap-pill-orange {
  background: #E65100;
  color: #fff;
  padding: 6px 16px;
  border-radius: 50px;
  font-weight: 600;
}

/* RIGHT SIDE CARD */
.csap-mcq-card {
  flex: 1 1 45%;
  min-width: 300px;
  background: #fff;
  padding: 28px;
  border-radius: 20px;
  box-shadow: 0 10px 30px rgba(0,0,0,0.12);
}

.csap-card-heading {
  font-size: 22px;
  font-weight: 700;
  margin-bottom: 16px;
}

.csap-tag-limited {
  background: #FFF3E0;
  color: #E65100;
  padding: 3px 10px;
  border-radius: 20px;
  margin-left: 8px;
  font-size: 12px;
}

.csap-card-columns {
  display: flex;
  gap: 20px;
  flex-wrap: wrap;
}

.csap-card-col {
  flex: 1 1 45%;
}

.csap-col-title {
  font-size: 18px;
  margin-bottom: 6px;
  font-weight: 700;
}

.csap-col-title.free {
  color: #388E3C;
}

.csap-col-title.paid {
  color: #E65100;
}

.csap-mcq-list.small li {
  margin-bottom: 5px;
}

/* BUTTONS */
.csap-btn-row {
  margin-top: 18px;
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
}

.csap-btn {
  padding: 12px 22px;
  border-radius: 50px;
  font-weight: 600;
  text-decoration: none;
  font-size: 15px;
  display: inline-block;
  transition: 0.2s ease;
}

.csap-btn-primary {
  background: #E65100;
  color: #fff;
  box-shadow: 0 4px 12px rgba(230,81,0,0.3);
}

.csap-btn-primary:hover {
  transform: translateY(-2px);
}

.csap-btn-outline {
  border: 2px solid #E65100;
  color: #E65100;
}

.csap-btn-outline:hover {
  background: #FFE0B2;
}

/* MOBILE */
@media (max-width: 768px) {
  .csap-mcq-title { font-size: 30px; }
  .csap-mcq-wrapper { padding: 0 14px; }
}


/* GRID LAYOUT */
.csap-card-grid {
  max-width: 1200px;
  margin: 0 auto;
  padding: 40px 20px;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 22px;
}

/* CARD STYLE */
.csap-info-card {
  background: #ffffff;
  border-radius: 18px;
  padding: 24px;
  text-align: center;
  box-shadow: 0 6px 20px rgba(0,0,0,0.12);
  transition: 0.25s ease;
  border: 1px solid #eee;
}

.csap-info-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 12px 24px rgba(0,0,0,0.18);
}

/* ICON */
.csap-card-icon {
  font-size: 42px;
  margin-bottom: 10px;
}

/* TITLE */
.csap-card-title {
  font-size: 20px;
  font-weight: 700;
  color: #E65100;
  margin-bottom: 8px;
}

/* TEXT */
.csap-card-text {
  font-size: 14px;
  color: #555;
  margin-bottom: 18px;
  line-height: 1.5;
}

/* BUTTON */
.csap-card-btn {
  display: inline-block;
  padding: 10px 20px;
  border-radius: 50px;
  background: #fff3e0;
  color: #E65100;
  border: 2px solid #E65100;
  font-weight: 600;
  text-decoration: none;
  transition: 0.2s ease;
}

.csap-card-btn:hover {
  background: #ffd9b3;
}

/* BUY NOW SPECIAL */
.buy-now-card {
  border: 2px solid #E65100;
}

.buy-now-btn {
  background: #E65100;
  color: #fff;
}

.buy-now-btn:hover {
  background: #C74600;
}

/* === FADE UP ANIMATION === */
@keyframes fadeUp {
  0% {
    opacity: 0;
    transform: translateY(25px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

/* === FADE IN === */
@keyframes fadeIn {
  0% {
    opacity: 0;
  }
  100% {
    opacity: 1;
  }
}

/* === SCALE IN === */
@keyframes scaleIn {
  0% {
    opacity: 0;
    transform: scale(0.92);
  }
  100% {
    opacity: 1;
    transform: scale(1);
  }
}

/* --- APPLY ANIMATIONS TO SECTIONS --- */

/* HERO SECTION */
.csap-hero-inner,
.csap-hero-title,
.csap-hero-subtitle,
.csap-hero-text {
  animation: fadeUp 0.9s ease forwards;
}

/* MCQ SECTION ROW */
.csap-mcq-wrapper {
  opacity: 0;
  animation: fadeUp 1s ease forwards;
  animation-delay: 0.2s;
}

/* MCQ RIGHT CARD */
.csap-mcq-card {
  opacity: 0;
  animation: scaleIn 0.9s ease forwards;
  animation-delay: 0.3s;
}

/* LEFT TEXT OF MCQ */
.csap-mcq-left {
  opacity: 0;
  animation: fadeUp 1s ease forwards;
  animation-delay: 0.1s;
}

/* CTA SECTION */
.csap-cta-wrapper {
  opacity: 0;
  animation: fadeUp 1s ease forwards;
  animation-delay: 0.2s;
}

/* CARD GRID (Blog, Sample, Brochure, Schedule, Buy Now) */
.csap-info-card {
  opacity: 0;
  animation: fadeUp 1s ease forwards;
}

.csap-info-card:nth-child(1) { animation-delay: 0.1s; }
.csap-info-card:nth-child(2) { animation-delay: 0.2s; }
.csap-info-card:nth-child(3) { animation-delay: 0.3s; }
.csap-info-card:nth-child(4) { animation-delay: 0.4s; }
.csap-info-card:nth-child(5) { animation-delay: 0.5s; }

/* BUTTON HOVER ANIMATION */
.csap-btn,
.csap-card-btn {
  transition: 0.25s ease;
}

.csap-btn:hover,
.csap-card-btn:hover {
  transform: translateY(-3px);
}

/* SMALL WIGGLE ANIMATION FOR BUY NOW (ATTENTION CATCHER) */
@keyframes wiggle {
  0%, 100% { transform: rotate(0); }
  25% { transform: rotate(2deg); }
  75% { transform: rotate(-2deg); }
}

.buy-now-btn:hover {
  animation: wiggle 0.4s ease-in-out;
}

Card 1 → 0.1s delay  
Card 2 → 0.2s delay  
Card 3 → 0.3s delay  
Card 4 → 0.4s delay  
Card 5 → 0.5s delay  

/* BASE ANIMATION STATE */
.csap-animate {
  opacity: 0;
  transform: translateY(25px);
  transition: opacity 0.8s ease, transform 0.8s ease;
}

/* WHEN VISIBLE */
.csap-animate.animate-in {
  opacity: 1;
  transform: translateY(0);
}

/* STAGGER FOR CARDS */
.csap-card-grid .csap-info-card {
  transition-delay: 0.1s;
}

.csap-card-grid .csap-info-card:nth-child(2) {
  transition-delay: 0.2s;
}
.csap-card-grid .csap-info-card:nth-child(3) {
  transition-delay: 0.3s;
}
.csap-card-grid .csap-info-card:nth-child(4) {
  transition-delay: 0.4s;
}
.csap-card-grid .csap-info-card:nth-child(5) {
  transition-delay: 0.5s;
}

/* Button hover (keep this) */
.csap-btn,
.csap-card-btn {
  transition: 0.25s ease;
}
.csap-btn:hover,
.csap-card-btn:hover {
  transform: translateY(-3px);
}

/* Wiggle for Buy Now on hover */
@keyframes wiggle {
  0%, 100% { transform: rotate(0); }
  25% { transform: rotate(2deg); }
  75% { transform: rotate(-2deg); }
}
.buy-now-btn:hover {
  animation: wiggle 0.4s ease-in-out;
}
document.addEventListener('DOMContentLoaded', function () {
  const animatedEls = document.querySelectorAll('.csap-animate');

  if (!('IntersectionObserver' in window)) {
    // Fallback: show everything if browser is old
    animatedEls.forEach(el => el.classList.add('animate-in'));
    return;
  }

  const observer = new IntersectionObserver(
    entries => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('animate-in');
          observer.unobserve(entry.target);
        }
      });
    },
    { threshold: 0.2 }
  );

  animatedEls.forEach(el => observer.observe(el));
});
