/* ANIMATED GRADIENT TITLE STYLE   */
/* =============================== */

.mcq-animated-title {
  font-size: 42px;
  font-weight: 800;
  background: linear-gradient(90deg, #ff9800, #ff6f00, #e65100, #ff9800);
  background-size: 300% 100%;
  -webkit-background-clip: text;
  color: transparent;
  animation: mcqGradientMove 8s linear infinite;
  position: relative;
  display: inline-block;
  margin-bottom: 12px;
}

/* Moving gradient animation */
@keyframes mcqGradientMove {
  0%   { background-position: 0% 50%; }
  50%  { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

/* Glow pulse animation on hover */
.mcq-animated-title:hover {
  animation: mcqGradientMove 4s linear infinite, mcqGlow 1.5s ease-in-out infinite;
  cursor: pointer;
}

/* Glow pulse */
@keyframes mcqGlow {
  0%   { text-shadow: 0 0 0px rgba(255,136,0,0.0); }
  50%  { text-shadow: 0 0 18px rgba(255,136,0,0.8); }
  100% { text-shadow: 0 0 0px rgba(255,136,0,0.0); }
}

/* Mobile size fix */
@media (max-width: 768px) {
  .mcq-animated-title {
